const r = $json || {};
const plan = r.plan || {};
const tasks = Array.isArray(plan.tasks) ? plan.tasks : [];
const selections = Array.isArray(r.selections) ? r.selections : [];
const runtime = r.runtimeTaskState && typeof r.runtimeTaskState === 'object' ? r.runtimeTaskState : {};
const resource = r.resourceDecision && typeof r.resourceDecision === 'object' ? r.resourceDecision : {};
const permission = r.permissionState && typeof r.permissionState === 'object' ? r.permissionState : {};
const approval = r.approvalState && typeof r.approvalState === 'object' ? r.approvalState : {};

const selectionByTask = new Map(selections.map(x => [String(x.taskId), x.selection || {}]));
const stateByTask = new Map(Object.entries(runtime));
const envelopes = [];
const errors = [];

function state(taskId) { return String(stateByTask.get(String(taskId))?.status ?? stateByTask.get(String(taskId)) ?? 'pending').toLowerCase(); }
function depsSatisfied(task) {
  const deps = Array.isArray(task.dep) ? task.dep : (Array.isArray(task.dependencies) ? task.dependencies : []);
  return deps.every(d => ['completed','succeeded','success','skipped'].includes(state(d)));
}
function permissionAllowed(task) {
  const v = permission[String(task.taskId)] ?? permission.default ?? permission.status ?? permission.allowed;
  return v === true || ['allowed','approved','granted'].includes(String(v ?? '').toLowerCase());
}
function approvalAllowed(task) {
  if (task.approvalRequired !== true && task.requiresApproval !== true) return true;
  const v = approval[String(task.taskId)] ?? approval.default ?? approval.status ?? approval.approved;
  return v === true || ['approved','allowed'].includes(String(v ?? '').toLowerCase());
}
function resourceAllowed(task) {
  const v = resource[String(task.taskId)] ?? resource.default ?? resource.status ?? resource.allowed;
  if (v === undefined) return resource.defer !== true && resource.allowed !== false;
  return v === true || ['allowed','approved','ready','proceed'].includes(String(v).toLowerCase());
}

for (const task of tasks) {
  const taskId = String(task.taskId ?? '');
  const sel = selectionByTask.get(taskId) || {};
  let status = 'ready_for_gateway';
  let reason = 'all coordinator gates satisfied';
  if (!taskId) { status = 'blocked_invalid_task'; reason = 'task_id_required'; }
  else if (sel.status === 'unavailable' || sel.providerId == null) { status = 'provider_unavailable'; reason = sel.reason || 'no_selected_provider'; }
  else if (sel.status === 'deferred') { status = 'deferred_resource'; reason = sel.reason || 'provider_selection_deferred'; }
  else if (!resourceAllowed(task)) { status = 'deferred_resource'; reason = 'resource_gate_not_ready'; }
  else if (!permissionAllowed(task)) { status = 'blocked_permission'; reason = 'permission_not_allowed'; }
  else if (!approvalAllowed(task)) { status = 'blocked_approval'; reason = 'approval_required'; }
  else if (!depsSatisfied(task)) { status = 'blocked_dependency'; reason = 'dependency_not_satisfied'; }

  envelopes.push({
    requestId: r.requestId, traceId: r.traceId, sessionId: r.sessionId, jobId: r.jobId || null,
    taskId, task: task.task ?? null, args: task.args ?? {}, dependencies: task.dep ?? task.dependencies ?? [],
    selectedProvider: sel.providerId ?? null, selectedModel: sel.model ?? null, executionMode: sel.executionMode ?? null,
    selectedTool: task.selectedTool ?? task.tool ?? null,
    permissionState: permission[taskId] ?? permission.default ?? permission.status ?? null,
    approvalState: approval[taskId] ?? approval.default ?? approval.status ?? null,
    resourceDecision: resource[taskId] ?? resource.default ?? resource.status ?? resource.allowed ?? null,
    status, reason, directExecution: false, gatewayDispatchRequired: status === 'ready_for_gateway',
    timing: { createdAt: new Date().toISOString() }, retryHistory: [], fallbackHistory: []
  });
}

if (!tasks.length) errors.push('plan_tasks_required');
const readyCount = envelopes.filter(x => x.status === 'ready_for_gateway').length;
return {
  valid: errors.length === 0, errors, schema: 'jarvis.compatible.execution-plan.v1',
  requestId: r.requestId, traceId: r.traceId, sessionId: r.sessionId, jobId: r.jobId || null, stage: 'task-execution-coordination',
  envelopes, readyCount, taskCount: envelopes.length, directExecution: false, gatewayDispatchRequired: readyCount > 0,
  executionAllowed: readyCount > 0,
  executionReason: readyCount > 0 ? 'ready tasks must be dispatched through existing gateway; coordinator performs no direct execution' : 'no task is currently dispatchable',
  generatedAt: new Date().toISOString()
};
